// re:dose wordmark (from redose-logo.webp with the faint background art removed, 96 px tall), inlined because Dives can't load external images.
const LOGO = 'data:image/png;base64,';

// Erowid's favicon (64 px ring logo, resized to 40 px), used on the source badge that links back to each report.
const EROWID_ICON = 'data:image/png;base64,';
const TRIPSIT_ICON = 'data:image/png;base64,';
const SEI_ICON = 'data:image/png;base64,';
const PW_ICON = 'data:image/png;base64,';
const MOTHERDUCK_ICON = 'data:image/png;base64,';
export const LOADING_PILL = 'data:image/gif;base64,'; // re:dose's 8-bit pill with electrons, recoloured white and lavender, 112px (shown at 56)

const DB = '"sourcing"."main"';
const N = (v: unknown): number => (v == null ? 0 : Number(v));
const S = (v: unknown): string => (v == null ? '' : String(v));
const esc = (s: string) => s.replace(/'/g, "''");
const L = (v: unknown): string[] => {
	if (v == null) return [];
	if (Array.isArray(v)) return v.map(String);
	const o = v as { values?: ArrayLike<unknown>; toArray?: () => ArrayLike<unknown> };
	const vals = o.values ?? o.toArray?.();
	return vals ? Array.from(vals).map(String) : [];
};

const rows = (q: { data?: unknown }) => (Array.isArray(q.data) ? (q.data as Record<string, unknown>[]) : []);

// ── SQL builders ──────────────────────────────────────────────────

const reportsCTE = (sub: string, single: boolean) => `
reports AS (
  SELECT r.id AS report_id, coalesce(m.canonical, r.substance) AS primary_sub,
         len(list_distinct(r.substances)) AS n_subs
  FROM ${DB}."experience_reports" r
  LEFT JOIN ${DB}."erowid_substance_map" m ON m.erowid_name = r.substance
),
sel AS (
  SELECT report_id, n_subs FROM reports
  WHERE primary_sub = '${esc(sub)}'${single ? ' AND n_subs = 1' : ''}
)`;

// Annotated, timed observations for whatever report set the `sel` CTE defines.
const obsFrom = (selCTE: string) => `${selCTE},
obs AS (
  SELECT o.report_id, o.obs_index, o.sentiment, o.description, o.time_relative, h.hrs,
    CASE WHEN h.hrs < 0.25 THEN 0 WHEN h.hrs < 0.5 THEN 1 WHEN h.hrs < 1 THEN 2 WHEN h.hrs < 2 THEN 3
         WHEN h.hrs < 3 THEN 4 WHEN h.hrs < 4 THEN 5 WHEN h.hrs < 6 THEN 6 WHEN h.hrs < 8 THEN 7
         WHEN h.hrs < 12 THEN 8 WHEN h.hrs < 24 THEN 9 ELSE 10 END AS bin,
    CASE WHEN h.hrs < 0.5 THEN 0 WHEN h.hrs < 2 THEN 1 WHEN h.hrs < 4 THEN 2 WHEN h.hrs < 8 THEN 3
         WHEN h.hrs < 24 THEN 4 ELSE 5 END AS phase
  FROM ${DB}."llm_observations" o
  JOIN sel USING (report_id),
  LATERAL (
    SELECT TRY_CAST(regexp_extract(o.time_relative, '^T\\+~?(\\d+):(\\d{2})', 1) AS INTEGER)
         + TRY_CAST(regexp_extract(o.time_relative, '^T\\+~?(\\d+):(\\d{2})', 2) AS INTEGER) / 60.0 AS hrs
  ) h
  WHERE h.hrs IS NOT NULL
),
eff AS (
  SELECT o.*, e.effect_name
  FROM obs o
  JOIN ${DB}."llm_observation_effects" e USING (report_id, obs_index)
  WHERE e.confidence <> 'low'
)`;
const obsCTE = (sub: string, single: boolean) => obsFrom(reportsCTE(sub, single));

// One-sentence explainer per effect from the Subjective Effect Index / PsychonautWiki descriptions, cleaned of
// scraper artifacts (glued-on names, [n] citations, parentheticals, missing spaces between sentences).
const effectInfoSQL = `
SELECT lower(name) AS k, name, category, url,
  trim(regexp_extract(
    regexp_replace(regexp_replace(regexp_replace(regexp_replace(
      CASE WHEN starts_with(description, name) THEN name || ' ' || substr(description, len(name) + 1) ELSE description END,
      '\\[\\d+\\]', '', 'g'), '\\s*\\([^)]*\\)', '', 'g'), '([.!?])([A-Z])', '\\1 \\2', 'g'), '\\s+', ' ', 'g'),
    '^(.*?[.!?])(\\s|$)', 1)) AS blurb
FROM ${DB}."effects"
WHERE description IS NOT NULL AND len(description) > 20`;

const subIdSQL = (sub: string) => `(SELECT id FROM ${DB}."substances" WHERE name = '${esc(sub)}')`;

const substanceListSQL = `
WITH reports AS (
  SELECT r.id AS report_id, coalesce(m.canonical, r.substance) AS primary_sub,
         len(list_distinct(r.substances)) AS n_subs
  FROM ${DB}."experience_reports" r
  LEFT JOIN ${DB}."erowid_substance_map" m ON m.erowid_name = r.substance
),
llm AS (SELECT DISTINCT report_id FROM ${DB}."llm_observations")
SELECT primary_sub, count(*) AS n_reports,
  count(*) FILTER (WHERE report_id IN (SELECT report_id FROM llm)) AS n_llm,
  count(*) FILTER (WHERE report_id IN (SELECT report_id FROM llm) AND n_subs = 1) AS n_llm_single
FROM reports
WHERE primary_sub IS NOT NULL AND primary_sub <> 'Unknown'
GROUP BY 1 HAVING n_llm >= 10
ORDER BY n_llm DESC, primary_sub`;

const kpiSQL = (sub: string, single: boolean) => `
WITH ${obsCTE(sub, single)},
neff AS (
  SELECT o.report_id, o.hrs, count(e.effect_name) AS n_eff
  FROM obs o
  LEFT JOIN ${DB}."llm_observation_effects" e
    ON e.report_id = o.report_id AND e.obs_index = o.obs_index AND e.confidence <> 'low'
  GROUP BY o.report_id, o.obs_index, o.hrs
),
per AS (
  SELECT report_id,
    min(hrs) FILTER (WHERE n_eff > 0) AS onset,
    arg_max(hrs, n_eff * 1000 - hrs) FILTER (WHERE hrs < 24) AS peak,
    max(hrs) FILTER (WHERE n_eff > 0 AND hrs < 24) AS last_eff
  FROM neff GROUP BY 1
),
ex AS (SELECT e.* FROM ${DB}."llm_extractions" e JOIN sel USING (report_id))
SELECT
  (SELECT count(*) FROM sel) AS n_reports,
  (SELECT count(DISTINCT report_id) FROM obs) AS n_llm,
  (SELECT count(*) FROM obs) AS n_obs,
  (SELECT count(*) FROM ex) AS n_ex,
  (SELECT 100.0 * avg((overall_sentiment = 'positive')::INT) FROM ex) AS pct_pos,
  (SELECT 100.0 * avg((overall_sentiment = 'negative')::INT) FROM ex) AS pct_neg,
  (SELECT 100.0 * avg((overall_sentiment = 'mixed')::INT) FROM ex) AS pct_mixed,
  (SELECT 100.0 * avg(would_repeat::INT) FROM ex) AS pct_repeat,
  (SELECT count(would_repeat) FROM ex) AS n_repeat,
  median(onset) AS onset_h, quantile_cont(onset, 0.25) AS onset_p25, quantile_cont(onset, 0.75) AS onset_p75,
  median(peak) AS peak_h, quantile_cont(peak, 0.25) AS peak_p25, quantile_cont(peak, 0.75) AS peak_p75,
  median(last_eff) AS last_h, quantile_cont(last_eff, 0.25) AS last_p25, quantile_cont(last_eff, 0.75) AS last_p75
FROM per`;

const phaseDenomSQL = (obs: string) => `
WITH ${obs}
SELECT phase, count(DISTINCT report_id) AS n_rep, count(*) AS n_obs,
  100.0 * avg((sentiment = 'negative')::INT) AS pct_neg
FROM obs GROUP BY phase ORDER BY phase`;

const phaseEffSQL = (obs: string) => `
WITH ${obs}
SELECT phase, effect_name, count(DISTINCT report_id) AS c
FROM eff GROUP BY phase, effect_name
QUALIFY row_number() OVER (PARTITION BY phase ORDER BY count(DISTINCT report_id) DESC, effect_name) <= 5
ORDER BY phase, c DESC`;

const binSQL = (obs: string) => `
WITH ${obs}
SELECT bin, count(DISTINCT report_id) AS n_rep, count(*) AS n_obs,
  sum((sentiment = 'positive')::INT) AS pos, sum((sentiment = 'mixed')::INT) AS mixed,
  sum((sentiment = 'negative')::INT) AS neg, sum((sentiment NOT IN ('positive','mixed','negative') OR sentiment IS NULL)::INT) AS neu
FROM obs GROUP BY bin ORDER BY bin`;

const heatSQL = (obs: string) => `
WITH ${obs},
top AS (
  SELECT effect_name, count(DISTINCT report_id) AS n
  FROM eff GROUP BY 1 ORDER BY 2 DESC, 1 LIMIT 18
)
SELECT e.effect_name, e.bin, count(DISTINCT e.report_id) AS c, any_value(t.n) AS n_total
FROM eff e JOIN top t USING (effect_name)
GROUP BY ALL`;

const yearsSQL = (sub: string, single: boolean) => `
WITH ${reportsCTE(sub, single)},
yrs AS (
  SELECT year(r.publication_date) AS yr, count(*) AS n
  FROM sel JOIN ${DB}."experience_reports" r ON r.id = sel.report_id
  WHERE r.publication_date IS NOT NULL GROUP BY 1
)
SELECT s.yr, coalesce(yrs.n, 0) AS n
FROM generate_series(2000, 2025) AS s(yr) LEFT JOIN yrs USING (yr)
ORDER BY s.yr`;

const examplesSQL = (sub: string, single: boolean, effect: string) => `
WITH ${obsCTE(sub, single)}
SELECT report_id, time_relative, bin, sentiment, description
FROM eff WHERE effect_name = '${esc(effect)}'
ORDER BY hrs, report_id LIMIT 60`;

const profileSQL = (sub: string, single: boolean) => `
WITH ${obsCTE(sub, single)},
ref AS (
  SELECT lower(ef.name) AS lname
  FROM ${DB}."substance_effects" se JOIN ${DB}."effects" ef ON ef.id = se.effect_id
  WHERE se.substance_id = ${subIdSQL(sub)}
),
first_seen AS (SELECT report_id, effect_name, min(hrs) AS first_h FROM eff GROUP BY ALL),
first_med AS (SELECT effect_name, median(first_h) AS med_first FROM first_seen WHERE first_h < 48 GROUP BY 1),
denom AS (SELECT count(DISTINCT report_id) AS n FROM obs)
SELECT e.effect_name,
  count(DISTINCT e.report_id) AS n_rep,
  100.0 * count(DISTINCT e.report_id) / any_value(denom.n) AS pct_reports,
  any_value(fm.med_first) AS med_first_h,
  100.0 * avg((e.sentiment = 'negative')::INT) AS pct_neg,
  bool_or(lower(e.effect_name) IN (SELECT lname FROM ref)) AS in_ref,
  (SELECT count(*) FROM ref) AS n_ref,
  any_value(ef.category) AS category
FROM eff e
CROSS JOIN denom
LEFT JOIN first_med fm USING (effect_name)
LEFT JOIN ${DB}."effects" ef ON lower(ef.name) = lower(e.effect_name)
GROUP BY e.effect_name
ORDER BY n_rep DESC, e.effect_name
LIMIT 40`;

const refMissingSQL = (sub: string, single: boolean) => `
WITH ${obsCTE(sub, single)}
SELECT ef.name
FROM ${DB}."substance_effects" se JOIN ${DB}."effects" ef ON ef.id = se.effect_id
WHERE se.substance_id = ${subIdSQL(sub)}
  AND lower(ef.name) NOT IN (SELECT lower(effect_name) FROM eff)
ORDER BY ef.name`;

const roaSQL = (sub: string) => `
SELECT route, replace(dose_units, 'μg', 'µg') AS dose_units, dose_threshold, dose_light_min, dose_common_min,
  dose_common_max, dose_strong_max, dose_heavy, duration_onset, duration_comeup, duration_peak,
  duration_offset, duration_total
FROM ${DB}."routes_of_administration"
WHERE substance_id = ${subIdSQL(sub)}
ORDER BY route`;

const doseSQL = (sub: string, single: boolean) => `
WITH ${reportsCTE(sub, single)},
roa AS (
  SELECT *, replace(dose_units, 'μg', 'µg') AS u, count(*) OVER () AS n_routes
  FROM ${DB}."routes_of_administration"
  WHERE substance_id = ${subIdSQL(sub)}
    AND replace(dose_units, 'μg', 'µg') IN ('mg', 'g', 'µg') AND dose_common_min IS NOT NULL
),
d AS (
  SELECT d.report_id,
    CASE d.route WHEN 'IV' THEN 'intravenous' WHEN 'IM' THEN 'intramuscular' WHEN 'vaporized' THEN 'smoked' ELSE d.route END AS route_n,
    CASE lower(d.amount_unit) WHEN 'mg' THEN d.amount_value WHEN 'g' THEN d.amount_value * 1000
      WHEN 'ug' THEN d.amount_value / 1000 WHEN 'µg' THEN d.amount_value / 1000 END AS mg
  FROM ${DB}."report_doses" d JOIN sel USING (report_id)
  WHERE d.canonical_substance = '${esc(sub)}' AND d.amount_value > 0
),
dj AS (
  SELECT d.report_id, roa.route,
    sum(d.mg * CASE roa.u WHEN 'mg' THEN 1 WHEN 'g' THEN 0.001 ELSE 1000 END) AS total,
    any_value(roa.u) AS unit, any_value(roa.dose_threshold) AS thr, any_value(roa.dose_common_min) AS cmin,
    any_value(roa.dose_common_max) AS cmax, any_value(roa.dose_heavy) AS heavy
  FROM d JOIN roa ON roa.route = d.route_n OR (roa.n_routes = 1 AND d.route_n IS DISTINCT FROM roa.route)
  WHERE d.mg IS NOT NULL
  GROUP BY 1, 2
),
banded AS (
  SELECT report_id, route, unit, total,
    CASE WHEN total < thr THEN 0 WHEN total < cmin THEN 1 WHEN total <= cmax THEN 2
         WHEN heavy IS NULL OR total < heavy THEN 3 ELSE 4 END AS band
  FROM dj
),
val AS (
  SELECT report_id, avg(valence) AS v FROM ${DB}."timeline_sentiment"
  WHERE report_id IN (SELECT report_id FROM banded) GROUP BY 1
)
SELECT b.route, b.unit, b.band, count(*) AS n_reports, median(b.total) AS median_dose,
  avg(val.v) AS avg_valence, count(val.v) AS n_val,
  count(e.report_id) AS n_llm,
  100.0 * avg((e.overall_sentiment = 'negative')::INT) AS pct_neg
FROM banded b
LEFT JOIN val USING (report_id)
LEFT JOIN ${DB}."llm_extractions" e USING (report_id)
GROUP BY ALL ORDER BY b.route, b.band`;

const doseCoverageSQL = (sub: string, single: boolean) => `
WITH ${reportsCTE(sub, single)}
SELECT count(*) AS n_rows, count(DISTINCT d.report_id) AS n_rep,
  count(*) FILTER (WHERE d.amount_value > 0) AS n_numeric,
  count(*) FILTER (WHERE d.amount_value > 0 AND lower(d.amount_unit) IN ('mg','g','ug','µg')) AS n_mass
FROM ${DB}."report_doses" d JOIN sel USING (report_id)
WHERE d.canonical_substance = '${esc(sub)}'`;

const otherUnitsSQL = (sub: string) => `
SELECT amount_unit AS u, count(*) AS n FROM ${DB}."report_doses"
WHERE canonical_substance = '${esc(sub)}' AND amount_unit IS NOT NULL
  AND lower(amount_unit) NOT IN ('mg','g','ug','µg')
GROUP BY 1 ORDER BY 2 DESC LIMIT 5`;

const subsNamesCTE = `
subs AS (
  SELECT id, name,
    list_distinct(list_transform(coalesce(common_names, []), x -> lower(x)) || [lower(name)]
      || list_filter(list_transform(string_split(name, ' '), x -> lower(x)), x -> len(x) > 4)) AS names,
    list_transform(coalesce(chemical_class, []) || coalesce(psychoactive_class, []), x -> lower(x)) AS classes
  FROM ${DB}."substances"
)`;

// Interaction severity for each (a, b) pair produced by `prSelect`. Matches the interactions table by
// name, common name and class in both directions; substances missing from `substances` (e.g. Lithium)
// fall back to their own name.
// Abbreviations the interaction notes use for things our substance table spells out (or doesn't list).
const ALIAS_SQL = (col: string) => `CASE lower(${col})
      WHEN 'selective serotonin reuptake inhibitor' THEN ['ssri', 'ssris']
      WHEN 'serotonin-norepinephrine reuptake inhibitor' THEN ['snri', 'snris']
      WHEN 'monoamine oxidase inhibitor' THEN ['maoi', 'maois']
      WHEN 'dextromethorphan' THEN ['dxm']
      WHEN 'methoxetamine' THEN ['mxe']
      WHEN 'diphenhydramine' THEN ['dph']
      WHEN 'nitrous' THEN ['nitrous', 'n2o']
      ELSE [] END`;

const pairSevCTEs = (prSelect: string) => `${subsNamesCTE},
pr AS (${prSelect}),
px AS (
  SELECT pr.a, pr.b, sa.id AS a_id, sb.id AS b_id,
    coalesce(sa.names, [lower(pr.a)]) || ${ALIAS_SQL('pr.a')} AS a_names, coalesce(sa.classes, []) AS a_cls,
    coalesce(sb.names, [lower(pr.b)]) || ${ALIAS_SQL('pr.b')} AS b_names, coalesce(sb.classes, []) AS b_cls
  FROM pr LEFT JOIN subs sa ON sa.name = pr.a LEFT JOIN subs sb ON sb.name = pr.b
),
oldsev AS (
  SELECT px.a, px.b,
    -- A match on a broad class word ("Depressants", "Stimulants"…) is too blunt to call a pair dangerous
    -- (it once flagged alcohol + nicotine), so it caps at caution; name and specific-class matches keep theirs.
    max(CASE
      WHEN NOT ((i.substance_id = px.a_id AND (list_contains(px.b_names, lower(i.interacts_with)) OR list_contains(px.b_names, rtrim(lower(i.interacts_with), 's'))))
             OR (i.substance_id = px.b_id AND (list_contains(px.a_names, lower(i.interacts_with)) OR list_contains(px.a_names, rtrim(lower(i.interacts_with), 's')))))
        AND rtrim(lower(i.interacts_with), 's') IN ('stimulant', 'depressant', 'psychedelic', 'dissociative', 'deliriant', 'entactogen', 'hallucinogen', 'cannabinoid')
      THEN least(CASE i.severity WHEN 'dangerous' THEN 3 WHEN 'unsafe' THEN 2 WHEN 'uncertain' THEN 1 END, 1)
      ELSE CASE i.severity WHEN 'dangerous' THEN 3 WHEN 'unsafe' THEN 2 WHEN 'uncertain' THEN 1 END END) AS sev,
    string_agg(DISTINCT i.interacts_with, ', ') AS via
  FROM px
  LEFT JOIN ${DB}."interactions" i ON
    (i.substance_id = px.a_id AND (list_contains(px.b_names, lower(i.interacts_with)) OR list_contains(px.b_names, rtrim(lower(i.interacts_with), 's'))
       OR list_contains(px.b_cls, lower(i.interacts_with)) OR list_contains(px.b_cls, rtrim(lower(i.interacts_with), 's'))))
    OR (i.substance_id = px.b_id AND (list_contains(px.a_names, lower(i.interacts_with)) OR list_contains(px.a_names, rtrim(lower(i.interacts_with), 's'))
       OR list_contains(px.a_cls, lower(i.interacts_with)) OR list_contains(px.a_cls, rtrim(lower(i.interacts_with), 's'))))
  GROUP BY 1, 2
),
-- TripSit's combination chart (loaded by tripsit/load_tripsit.py) takes precedence when it covers the pair.
tsev AS (
  SELECT pr.a, pr.b, max(c.severity_rank) AS rank,
    arg_max(c.status, c.severity_rank) AS status, arg_max(c.note, c.severity_rank) AS note
  FROM pr
  JOIN ${DB}."tripsit_group_members" ma ON ma.substance = pr.a
  JOIN ${DB}."tripsit_group_members" mb ON mb.substance = pr.b
  JOIN ${DB}."tripsit_combos" c
    ON (c.group_a = ma.group_key AND c.group_b = mb.group_key) OR (c.group_a = mb.group_key AND c.group_b = ma.group_key)
  WHERE ma.group_key <> mb.group_key
  GROUP BY 1, 2
),
pairsev AS (
  SELECT pr.a, pr.b,
    CASE WHEN t.rank IS NOT NULL THEN nullif(t.rank, 0) ELSE o.sev END AS sev,
    CASE WHEN t.rank IS NOT NULL THEN 'TripSit' ELSE o.via END AS via,
    t.status, t.note
  FROM pr LEFT JOIN tsev t USING (a, b) LEFT JOIN oldsev o USING (a, b)
)`;

const comboSQL = (sub: string) => `
WITH ${reportsCTE(sub, false)},
co AS (
  SELECT DISTINCT d.report_id, d.canonical_substance AS co_sub
  FROM ${DB}."report_doses" d JOIN sel USING (report_id)
  WHERE d.canonical_substance IS NOT NULL AND d.canonical_substance <> '${esc(sub)}'
),
val AS (
  SELECT report_id, avg(valence) AS v FROM ${DB}."timeline_sentiment"
  WHERE report_id IN (SELECT report_id FROM sel) GROUP BY 1
),
${pairSevCTEs(`SELECT DISTINCT '${esc(sub)}' AS a, co_sub AS b FROM co`)},
alone AS (
  SELECT 0 AS ord, 'Alone (single-substance reports)' AS co_sub, count(*) AS n_reports, NULL::INT AS sev, NULL AS via,
    avg(val.v) AS avg_valence, count(val.v) AS n_val, count(e.report_id) AS n_llm,
    100.0 * avg((e.overall_sentiment = 'negative')::INT) AS pct_neg
  FROM sel LEFT JOIN val USING (report_id) LEFT JOIN ${DB}."llm_extractions" e USING (report_id)
  WHERE sel.n_subs = 1
),
combos AS (
  SELECT 1 AS ord, co.co_sub, count(*) AS n_reports, any_value(ps.sev) AS sev, any_value(ps.via) AS via,
    avg(val.v) AS avg_valence, count(val.v) AS n_val, count(e.report_id) AS n_llm,
    100.0 * avg((e.overall_sentiment = 'negative')::INT) AS pct_neg
  FROM co LEFT JOIN pairsev ps ON ps.b = co.co_sub LEFT JOIN val USING (report_id)
  LEFT JOIN ${DB}."llm_extractions" e USING (report_id)
  GROUP BY co.co_sub
  ORDER BY n_reports DESC
  LIMIT 15
)
SELECT * FROM alone UNION ALL SELECT * FROM combos
ORDER BY ord, n_reports DESC`;

const interactionsSQL = (sub: string) => `
SELECT CASE severity WHEN 'dangerous' THEN 3 WHEN 'unsafe' THEN 2 ELSE 1 END AS sev,
  list(DISTINCT interacts_with ORDER BY interacts_with) AS items
FROM ${DB}."interactions"
WHERE substance_id = ${subIdSQL(sub)}
GROUP BY 1 ORDER BY 1 DESC`;

const compareSQL = `
WITH reports AS (
  SELECT r.id AS report_id, coalesce(m.canonical, r.substance) AS primary_sub,
         len(list_distinct(r.substances)) AS n_subs
  FROM ${DB}."experience_reports" r
  LEFT JOIN ${DB}."erowid_substance_map" m ON m.erowid_name = r.substance
),
obs AS (
  SELECT o.report_id, o.obs_index,
    TRY_CAST(regexp_extract(o.time_relative, '^T\\+~?(\\d+):(\\d{2})', 1) AS INTEGER)
      + TRY_CAST(regexp_extract(o.time_relative, '^T\\+~?(\\d+):(\\d{2})', 2) AS INTEGER) / 60.0 AS hrs
  FROM ${DB}."llm_observations" o
),
neff AS (
  SELECT o.report_id, o.hrs, count(e.effect_name) AS n_eff
  FROM obs o
  LEFT JOIN ${DB}."llm_observation_effects" e
    ON e.report_id = o.report_id AND e.obs_index = o.obs_index AND e.confidence <> 'low'
  WHERE o.hrs IS NOT NULL
  GROUP BY o.report_id, o.obs_index, o.hrs
),
per AS (
  SELECT report_id,
    min(hrs) FILTER (WHERE n_eff > 0) AS onset,
    arg_max(hrs, n_eff * 1000 - hrs) FILTER (WHERE hrs < 24) AS peak,
    max(hrs) FILTER (WHERE n_eff > 0 AND hrs < 24) AS last_eff
  FROM neff GROUP BY 1
)
SELECT primary_sub, count(*) AS n, median(onset) AS onset_h, median(peak) AS peak_h, median(last_eff) AS last_h
FROM per JOIN reports USING (report_id)
WHERE n_subs = 1 AND primary_sub IS NOT NULL AND primary_sub <> 'Unknown'
GROUP BY 1 HAVING count(*) >= 10
ORDER BY peak_h`;

// ── Time-lapse SQL ────────────────────────────────────────────────

// Every substance with enough reports, plus the names people call it (common and street names, "|"-separated)
// so the Substances search can find "molly" or "yayo".
const pickListSQL = `
WITH sn AS (
  SELECT substance, lower(string_agg(street_name, '|')) AS terms
  FROM ${DB}."street_names" WHERE NOT coalesce(is_combo, false) GROUP BY 1
)
SELECT d.canonical_substance AS s, count(DISTINCT d.report_id) AS n,
  lower(array_to_string(coalesce(any_value(t.common_names), []), '|')) || '|' || coalesce(any_value(sn.terms), '') AS alias
FROM ${DB}."report_doses" d
LEFT JOIN ${DB}."substances" t ON t.name = d.canonical_substance
LEFT JOIN sn ON sn.substance = d.canonical_substance
WHERE d.canonical_substance IS NOT NULL
  AND d.report_id IN (SELECT report_id FROM ${DB}."report_timeline" WHERE timing_method <> 'dose_table')
GROUP BY 1 HAVING count(DISTINCT d.report_id) >= 10
ORDER BY n DESC, s`;

const coSQL = (sub: string) => `
SELECT d2.canonical_substance AS s, count(DISTINCT d1.report_id) AS n
FROM ${DB}."report_doses" d1 JOIN ${DB}."report_doses" d2 USING (report_id)
WHERE d1.canonical_substance = '${esc(sub)}' AND d2.canonical_substance IS NOT NULL AND d2.canonical_substance <> '${esc(sub)}'
GROUP BY 1 HAVING count(DISTINCT d1.report_id) >= 2`;

const onlyFilter = (subs: string[]) => `report_id IN (
    SELECT report_id FROM ${DB}."report_doses" WHERE canonical_substance IS NOT NULL
    GROUP BY 1 HAVING bool_and(canonical_substance IN (${subs.map((x) => `'${esc(x)}'`).join(', ')}))
  )`;
const reportListSQL = (sub: string, other?: string | null, only?: boolean) => `
WITH r AS (
  SELECT DISTINCT report_id FROM ${DB}."report_doses" WHERE canonical_substance = '${esc(sub)}'
  ${other ? `INTERSECT SELECT DISTINCT report_id FROM ${DB}."report_doses" WHERE canonical_substance = '${esc(other)}'` : ''}
  ${only ? `INTERSECT SELECT report_id FROM ${DB}."report_doses" WHERE ${onlyFilter(other ? [sub, other] : [sub])}` : ''}
),
marks AS (
  SELECT report_id, count(*) AS n_marks, max(t_offset) AS span
  FROM ${DB}."report_timeline" WHERE timing_method <> 'dose_table' AND report_id IN (SELECT report_id FROM r)
  GROUP BY 1
)
SELECT e.id AS report_id, e.experience_year AS yr, len(e.body) AS chars, m.n_marks,
  x.overall_sentiment AS sentiment, x.report_id IS NOT NULL AS read_closely,
  array_to_string(list_distinct(e.substances), ' · ') AS subs,
  left(regexp_replace(e.body, '\\s+', ' ', 'g'), 150) AS opening
FROM marks m
JOIN ${DB}."experience_reports" e ON e.id = m.report_id
LEFT JOIN ${DB}."llm_extractions" x ON x.report_id = m.report_id
WHERE m.n_marks >= 3 AND m.span > 0
ORDER BY read_closely DESC, m.n_marks DESC, e.id
LIMIT 40`;

const reportSQL = (id: string) => `
SELECT r.id, r.body, r.experience_year AS yr, r.gender, r.age,
  array_to_string(list_distinct(r.substances), ' · ') AS subs,
  x.overall_sentiment AS overall, x.would_repeat AS repeat
FROM ${DB}."experience_reports" r
LEFT JOIN ${DB}."llm_extractions" x ON x.report_id = r.id
WHERE r.id = '${esc(id)}'`;

const reportMarksSQL = (id: string) => `
SELECT rt.t_offset AS t, rt.timing_method AS method, rt.raw_value AS raw, rt.text_snippet AS snippet,
  any_value(ts.valence) AS valence
FROM ${DB}."report_timeline" rt
LEFT JOIN ${DB}."timeline_sentiment" ts
  ON ts.report_id = rt.report_id AND ts.t_offset = rt.t_offset AND ts.timing_method = rt.timing_method
WHERE rt.report_id = '${esc(id)}' AND rt.timing_method <> 'dose_table' AND rt.t_offset IS NOT NULL
GROUP BY ALL`;

const reportDosesSQL = (id: string) => `
WITH story AS (
  SELECT (d->>'$.order')::INT AS ord,
    trim(regexp_replace(d->>'$.substance', '\\s*\\(.*\\)$', '')) AS raw,
    d->>'$.amount' AS amount, d->>'$.route' AS route,
    TRY_CAST(regexp_extract(d->>'$.time_relative', '^T\\+~?(\\d+):(\\d{2})', 1) AS INTEGER)
      + TRY_CAST(regexp_extract(d->>'$.time_relative', '^T\\+~?(\\d+):(\\d{2})', 2) AS INTEGER) / 60.0 AS t
  FROM ${DB}."llm_extractions", unnest(from_json(extraction->'$.doses', '["json"]')) AS u(d)
  WHERE report_id = '${esc(id)}'
),
named AS (
  SELECT ord, amount, route, t, coalesce(
    (SELECT s.name FROM ${DB}."substances" s WHERE lower(s.name) = lower(raw) LIMIT 1),
    (SELECT s.name FROM ${DB}."substances" s WHERE list_contains(list_transform(coalesce(s.common_names, []), x -> lower(x)), lower(raw)) LIMIT 1),
    raw) AS sub
  FROM story
),
dose_table AS (
  SELECT row_number() OVER () AS ord, coalesce(canonical_substance, substance) AS sub, amount_raw AS amount, route, t_offset AS t
  FROM ${DB}."report_doses" WHERE report_id = '${esc(id)}'
)
SELECT sub, amount, route, t, ord FROM named
UNION ALL
SELECT sub, amount, route, t, ord FROM dose_table WHERE NOT EXISTS (SELECT 1 FROM named)
ORDER BY t NULLS LAST, ord`;

// Typical onset / peak / last-effect times per substance (and per route), from closely read reports whose first
// dose was that substance. Used to draw each dose's expected effect curve.
const ROUTE_CASE = (col: string) => `CASE lower(${col})
      WHEN 'inhaled' THEN 'smoked' WHEN 'vaporized' THEN 'smoked' WHEN 'vaped' THEN 'smoked'
      WHEN 'iv' THEN 'injected' WHEN 'intravenous' THEN 'injected' WHEN 'im' THEN 'injected' WHEN 'injected' THEN 'injected'
      WHEN 'snorted' THEN 'insufflated' ELSE lower(${col}) END`;
const timingSQL = (subs: string[]) => `
WITH fd AS (
  SELECT report_id, extraction->>'$.doses[0].substance' AS sub, ${ROUTE_CASE(`extraction->>'$.doses[0].route'`)} AS route
  FROM ${DB}."llm_extractions"
  WHERE extraction->>'$.doses[0].substance' IN (${subs.length ? subs.map((s) => `'${esc(s)}'`).join(', ') : "''"})
),
o AS (
  SELECT fd.sub, fd.route, ob.report_id,
    TRY_CAST(regexp_extract(ob.time_relative, '^T\\+~?(\\d+):(\\d{2})', 1) AS INTEGER)
      + TRY_CAST(regexp_extract(ob.time_relative, '^T\\+~?(\\d+):(\\d{2})', 2) AS INTEGER) / 60.0 AS hrs,
    (SELECT count(*) FROM ${DB}."llm_observation_effects" e
      WHERE e.report_id = ob.report_id AND e.obs_index = ob.obs_index AND e.confidence <> 'low') AS n_eff
  FROM ${DB}."llm_observations" ob JOIN fd USING (report_id)
),
per AS (
  SELECT sub, route, report_id,
    min(hrs) FILTER (WHERE n_eff > 0) AS onset,
    arg_max(hrs, n_eff * 1000 - hrs) FILTER (WHERE hrs < 24) AS peak,
    max(hrs) FILTER (WHERE n_eff > 0 AND hrs < 24) AS last_eff
  FROM o WHERE hrs IS NOT NULL GROUP BY ALL
)
SELECT sub, coalesce(route, '*') AS route, count(*) AS n,
  median(onset) AS on_m, median(peak) AS pk_m, quantile_cont(peak, 0.75) AS pk_hi,
  median(last_eff) AS end_m, quantile_cont(last_eff, 0.75) AS end_hi
FROM per WHERE onset IS NOT NULL AND peak IS NOT NULL AND last_eff IS NOT NULL
GROUP BY GROUPING SETS ((sub, route), (sub))
HAVING count(*) >= 6`;

const effectToneSQL = `
SELECT lower(e.effect_name) AS k, avg((o.sentiment = 'negative')::INT) AS neg, avg((o.sentiment = 'positive')::INT) AS pos
FROM ${DB}."llm_observation_effects" e
JOIN ${DB}."llm_observations" o USING (report_id, obs_index)
WHERE e.confidence <> 'low'
GROUP BY 1`;

const reportPairsSQL = (subs: string[]) => {
	const list = `[${subs.map((x) => `'${esc(x)}'`).join(', ')}]`;
	return `
WITH ${pairSevCTEs(`SELECT a.x AS a, b.x AS b FROM unnest(${list}) AS a(x), unnest(${list}) AS b(x) WHERE a.x < b.x`)}
SELECT a, b, sev, via, status, note FROM pairsev WHERE sev IS NOT NULL OR status IS NOT NULL`;
};

const reportObsSQL = (id: string) => `
SELECT o.obs_index, o.time_relative, o.time_original, o.description, o.sentiment,
  TRY_CAST(regexp_extract(o.time_relative, '^T\\+~?(\\d+):(\\d{2})', 1) AS INTEGER)
    + TRY_CAST(regexp_extract(o.time_relative, '^T\\+~?(\\d+):(\\d{2})', 2) AS INTEGER) / 60.0 AS hrs,
  list(e.effect_name ORDER BY e.effect_name) FILTER (WHERE e.effect_name IS NOT NULL) AS effects
FROM ${DB}."llm_observations" o
LEFT JOIN ${DB}."llm_observation_effects" e
  ON e.report_id = o.report_id AND e.obs_index = o.obs_index AND e.confidence <> 'low'
WHERE o.report_id = '${esc(id)}'
GROUP BY ALL
ORDER BY hrs NULLS LAST, o.obs_index`;

// Effect prevalence over a substance-specific time window, in SLICES equal slices.
const SLICES = 16;
const pairSel = (a: string, b: string, only?: boolean) => `
sel AS (
  SELECT report_id FROM ${DB}."report_doses" WHERE canonical_substance = '${esc(a)}'
  INTERSECT
  SELECT report_id FROM ${DB}."report_doses" WHERE canonical_substance = '${esc(b)}'
  ${only ? `INTERSECT SELECT report_id FROM ${DB}."report_doses" WHERE ${onlyFilter([a, b])}` : ''}
)`;
const curveObs = (sub: string, other?: string | null, only?: boolean) => (other ? obsFrom(pairSel(sub, other, only)) : obsCTE(sub, !!only));
const curveSQL = (sub: string, horizon: number, other?: string | null, only?: boolean) => `
WITH ${curveObs(sub, other, only)},
top AS (
  SELECT effect_name FROM eff WHERE hrs < ${horizon}
  GROUP BY 1 ORDER BY count(DISTINCT report_id) DESC, 1 LIMIT 5
)
SELECT e.effect_name, floor(e.hrs / ${horizon / SLICES})::INT AS bin, count(DISTINCT e.report_id) AS c
FROM eff e JOIN top USING (effect_name)
WHERE e.hrs < ${horizon}
GROUP BY ALL`;
const curveDenSQL = (sub: string, horizon: number, other?: string | null, only?: boolean) => `
WITH ${curveObs(sub, other, only)}
SELECT floor(hrs / ${horizon / SLICES})::INT AS bin, count(DISTINCT report_id) AS n,
  avg(CASE sentiment WHEN 'positive' THEN 1 WHEN 'negative' THEN -1 ELSE 0 END) AS mood,
  (SELECT count(DISTINCT report_id) FROM obs WHERE hrs < ${horizon}) AS total
FROM obs WHERE hrs < ${horizon}
GROUP BY 1`;

// Tone of the writing over time across every report containing both substances (not only closely read ones).
const pairMoodSQL = (a: string, b: string, horizon: number) => `
WITH ${pairSel(a, b)}
SELECT floor(ts.t_offset / ${horizon / SLICES})::INT AS bin, avg(ts.valence) AS v, count(DISTINCT ts.report_id) AS n,
  (SELECT count(*) FROM sel) AS total
FROM ${DB}."timeline_sentiment" ts JOIN sel USING (report_id)
WHERE ts.t_offset >= 0 AND ts.t_offset < ${horizon}
GROUP BY 1`;

const classesSQL = `SELECT name, psychoactive_class[1] AS cls FROM ${DB}."substances"`;

// ── Browse & detail SQL ───────────────────────────────────────────

const effectsBrowseSQL = `
SELECT e.effect_name AS name, coalesce(any_value(ef.category), 'Other') AS category, count(DISTINCT e.report_id) AS n
FROM ${DB}."llm_observation_effects" e
LEFT JOIN ${DB}."effects" ef ON lower(ef.name) = lower(e.effect_name)
WHERE e.confidence <> 'low'
GROUP BY e.effect_name
ORDER BY n DESC, name`;

const cleanDesc = (col: string, nameCol: string) => `
  regexp_replace(regexp_replace(regexp_replace(regexp_replace(
    CASE WHEN starts_with(${col}, ${nameCol}) THEN ${nameCol} || ' ' || substr(${col}, len(${nameCol}) + 1) ELSE ${col} END,
    '\\[\\d+\\]', '', 'g'), '\\s*\\([^)]*\\)', '', 'g'), '([.!?])([A-Z])', '\\1 \\2', 'g'), '\\s+', ' ', 'g')`;

const effectDetailSQL = (name: string) => `
WITH fd AS (SELECT report_id, extraction->>'$.doses[0].substance' AS sub FROM ${DB}."llm_extractions"),
hits AS (
  SELECT DISTINCT e.report_id, o.sentiment
  FROM ${DB}."llm_observation_effects" e JOIN ${DB}."llm_observations" o USING (report_id, obs_index)
  WHERE lower(e.effect_name) = lower('${esc(name)}') AND e.confidence <> 'low'
),
subs AS (
  SELECT fd.sub, count(DISTINCT hits.report_id) AS n FROM hits JOIN fd USING (report_id)
  WHERE fd.sub IS NOT NULL GROUP BY 1 ORDER BY n DESC, fd.sub LIMIT 8
)
SELECT
  (SELECT any_value(category) FROM ${DB}."effects" WHERE lower(name) = lower('${esc(name)}')) AS category,
  (SELECT any_value(url) FROM ${DB}."effects" WHERE lower(name) = lower('${esc(name)}')) AS url,
  (SELECT any_value(${cleanDesc('description', 'name')}) FROM ${DB}."effects" WHERE lower(name) = lower('${esc(name)}')) AS description,
  (SELECT count(DISTINCT report_id) FROM hits) AS n_reports,
  (SELECT avg((sentiment = 'negative')::INT) FROM hits) AS neg,
  (SELECT avg((sentiment = 'positive')::INT) FROM hits) AS pos,
  (SELECT list(sub ORDER BY n DESC, sub) FROM subs) AS sub_names,
  (SELECT list(n ORDER BY n DESC, sub) FROM subs) AS sub_counts`;

// Names in the data that are really groups of drugs (Erowid files some reports under a category, and some
// specific drugs, like ether under inhalants, were folded into one). One timing curve can't describe a group.
const GROUPS = new Set(['Inhalants', 'Antidepressants', 'Opioids', 'Stimulants', 'Sedative', 'Barbiturates', 'Benzodiazepines', 'Substituted amphetamines', 'Selective serotonin reuptake inhibitor', 'Serotonin-norepinephrine reuptake inhibitor', 'Monoamine oxidase inhibitor']);
const isGroup = (name: string) => GROUPS.has(name);
// What reports filed under a group actually name.
const groupMembersSQL = (name: string) => `
SELECT substance AS name, count(DISTINCT report_id) AS n
FROM ${DB}."report_doses"
WHERE canonical_substance = '${esc(name)}' AND lower(substance) <> lower('${esc(name)}')
GROUP BY 1 ORDER BY n DESC, 1 LIMIT 8`;

const substanceDetailSQL = (name: string) => `
WITH fd AS (
  SELECT report_id FROM ${DB}."llm_extractions" WHERE extraction->>'$.doses[0].substance' = '${esc(name)}'
),
eff AS (
  SELECT e.effect_name, count(DISTINCT e.report_id) AS n
  FROM ${DB}."llm_observation_effects" e JOIN fd USING (report_id)
  WHERE e.confidence <> 'low' GROUP BY 1 ORDER BY n DESC, 1 LIMIT 10
)
SELECT s.name, s.summary, s.url, coalesce(s.psychoactive_class, []) AS cls, coalesce(s.chemical_class, []) AS chem,
  coalesce(s.common_names, []) AS aka, coalesce(s.cross_tolerances, []) AS cross_tol,
  s.tolerance_full, s.tolerance_zero, s.addiction_potential AS addiction, coalesce(s.toxicity, []) AS tox,
  EXISTS (SELECT 1 FROM ${DB}."tripsit_group_members" WHERE group_key = 'maois' AND substance = q.q) AS maoi,
  (SELECT count(*) FROM fd) AS n_read,
  (SELECT count(DISTINCT report_id) FROM ${DB}."report_doses" WHERE canonical_substance = '${esc(name)}') AS n_reports,
  (SELECT list(effect_name ORDER BY n DESC, effect_name) FROM eff) AS effects
FROM (SELECT '${esc(name)}' AS q) q
LEFT JOIN ${DB}."substances" s ON s.name = q.q`;

// Cross-tolerance: the substances table lists it as loose keywords ("psychedelics", "dopamine", "GABA|gabaergic"…).
// Group them into families; two substances share tolerance when their families overlap.
const tolCTE = `tol AS (
  SELECT name, list_distinct(list_filter(list_transform(coalesce(cross_tolerances, []), x -> CASE
      WHEN regexp_matches(lower(x), 'psychedelic|hallucinogen') THEN 'psychedelics'
      WHEN regexp_matches(lower(x), 'dopamin|stimulant') THEN 'stimulants'
      WHEN regexp_matches(lower(x), 'opioid') THEN 'opioids'
      WHEN regexp_matches(lower(x), 'dissociative') THEN 'dissociatives'
      WHEN regexp_matches(lower(x), 'benzo|thien|gaba|depressant') THEN 'benzos and other GABA drugs'
      WHEN regexp_matches(lower(x), 'cannabinoid') THEN 'cannabinoids'
      WHEN regexp_matches(lower(x), 'seroton|entactogen') THEN 'serotonergic drugs'
    END), f -> f IS NOT NULL)) AS fam
  FROM ${DB}."substances"
)`;
// The most-reported substances that share tolerance with this one.
const crossTolSQL = (name: string) => `
WITH ${tolCTE},
me AS (SELECT fam FROM tol WHERE name = '${esc(name)}'),
n AS (SELECT canonical_substance AS name, count(DISTINCT report_id) AS n FROM ${DB}."report_doses" WHERE canonical_substance IS NOT NULL GROUP BY 1)
SELECT t.name, list_intersect(t.fam, me.fam) AS shared, coalesce(n.n, 0) AS n
FROM tol t CROSS JOIN me LEFT JOIN n ON n.name = t.name
WHERE t.name <> '${esc(name)}' AND len(list_intersect(t.fam, me.fam)) > 0
ORDER BY n DESC, t.name LIMIT 10`;
// Which of these substances share tolerance with each other.
const tolPairsSQL = (subs: string[]) => {
	const list = subs.map((x) => `'${esc(x)}'`).join(', ') || "''";
	return `
WITH ${tolCTE}
SELECT a.name AS a, b.name AS b, list_intersect(a.fam, b.fam) AS shared
FROM tol a JOIN tol b ON a.name < b.name
WHERE a.name IN (${list}) AND b.name IN (${list}) AND len(list_intersect(a.fam, b.fam)) > 0`;
};
const sharesTol = (pairs: Record<string, unknown>[], x: string, y: string) =>
	pairs.find((p) => (S(p.a) === x && S(p.b) === y) || (S(p.a) === y && S(p.b) === x));

